 "path": ".openclaw/tmp/task-05717cbc.py",
 "content": "def transform(grid):
    # For each same-colored rectangular block, erase the smallest block; preserve largest.
    from collections import defaultdict
    cells=defaultdict(list)
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v: cells[v].append((r,c))
    # task pattern: multiple solid rectangles; return with smallest rectangle removed
    rects=[]
    for color, pts in cells.items():
        rs=[p[0] for p in pts]; cs=[p[1] for p in pts]
        rects.append((color,min(rs),max(rs),min(cs),max(cs)))
    out=[row[:] for row in grid]
    if len(rects)>1:
        sizes=[(b-a+1)*(d-c+1) for _,a,b,c,d in rects]
        i=sizes.index(min(sizes)); color,a,b,c,d=rects[i]
        for r in range(a,b+1):
            for col in range(c,d+1): out[r][col]=0
    return out
